int k = 0;
for (i = 1; i < n; i++)
    if (a[i] > a[k]) k = i;
printf("max=%d at %d\n", a[k], k);

/* 二维：记行列 */
int mi = 0, mj = 0;
for (i = 0; i < M; i++)
    for (j = 0; j < N; j++)
        if (a[i][j] > a[mi][mj]) { mi = i; mj = j; }
